  `source_word_normalized` varchar(255) NOT NULL,
  `target_word` varchar(255) NOT NULL,
  `target_word_normalized` varchar(255) NOT NULL,
  `duplicate_key` varchar(255) DEFAULT NULL,
  `reverse_word` varchar(255) DEFAULT NULL,
  `source_language` varchar(255) NOT NULL DEFAULT 'Bahasa A',
  `target_language` varchar(255) NOT NULL DEFAULT 'Bahasa B',
  `part_of_speech` varchar(255) DEFAULT NULL,
  `phonetic` varchar(255) DEFAULT NULL,
  `pronunciation_audio` varchar(255) DEFAULT NULL,
  `definition` text DEFAULT NULL,
  `usage_note` text DEFAULT NULL,
  `cultural_note` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'draft',
  `created_by` bigint unsigned DEFAULT NULL,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dictionary_entries_duplicate_key_unique` (`duplicate_key`),
  UNIQUE KEY `dictionary_entries_public_id_unique` (`public_id`),
  KEY `dictionary_entries_source_word_normalized_index` (`source_word_normalized`),
  KEY `dictionary_entries_target_word_normalized_index` (`target_word_normalized`),
  KEY `dictionary_entries_source_language_index` (`source_language`),
  KEY `dictionary_entries_target_language_index` (`target_language`),
  KEY `dictionary_entries_part_of_speech_index` (`part_of_speech`),
  KEY `dictionary_entries_category_id_foreign` (`category_id`),
  KEY `dictionary_entries_status_category_id_index` (`status`, `category_id`),
  KEY `dictionary_entries_status_part_of_speech_index` (`status`, `part_of_speech`),
  KEY `dictionary_entries_created_by_foreign` (`created_by`),
  KEY `dictionary_entries_reviewed_by_foreign` (`reviewed_by`),
  KEY `dictionary_entries_tolaki_word_normalized_index` (`tolaki_word_normalized`),
  KEY `dictionary_entries_indonesian_word_normalized_index` (`indonesian_word_normalized`),
  KEY `dictionary_entries_english_word_normalized_index` (`english_word_normalized`),
  CONSTRAINT `dictionary_entries_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `dictionary_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `dictionary_entries_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `dictionary_entries_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `example_sentences` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `dictionary_entry_id` bigint unsigned NOT NULL,
  `tolaki_sentence` text DEFAULT NULL,
  `indonesian_sentence` text DEFAULT NULL,
  `english_sentence` text DEFAULT NULL,
  `source_sentence` text NOT NULL,
  `target_sentence` text NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `example_sentences_dictionary_entry_id_foreign` (`dictionary_entry_id`),
  CONSTRAINT `example_sentences_dictionary_entry_id_foreign` FOREIGN KEY (`dictionary_entry_id`) REFERENCES `dictionary_entries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `dictionary_visits` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `path` varchar(255) NOT NULL,
