  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dictionary_visits_daily_unique` (`route_name`, `dictionary_entry_id`, `keyword`, `ip_hash`, `occurred_on`),
  KEY `dictionary_visits_route_name_index` (`route_name`),
  KEY `dictionary_visits_dictionary_entry_id_foreign` (`dictionary_entry_id`),
  KEY `dictionary_visits_keyword_index` (`keyword`),
  KEY `dictionary_visits_ip_hash_index` (`ip_hash`),
  KEY `dictionary_visits_occurred_on_index` (`occurred_on`),
  KEY `dictionary_visits_dictionary_entry_id_occurred_on_index` (`dictionary_entry_id`, `occurred_on`),
  KEY `dictionary_visits_occurred_on_ip_hash_index` (`occurred_on`, `ip_hash`),
  CONSTRAINT `dictionary_visits_dictionary_entry_id_foreign` FOREIGN KEY (`dictionary_entry_id`) REFERENCES `dictionary_entries` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
